        print(f"Running command: {cmd}")
    # Execute
    try:
        result = subprocess.run(
            cmd,
            shell=use_shell,
            cwd=cwd,
            env=env_dict,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
            text=True
