def is_none_string(val: any) -> bool:
    """Check if a string represents a None value.

    Returns True if *val* is a string that, ignoring case and surrounding
    whitespace, matches one of the well-known string representations of
    a null value (for example: "None", "null", "nil", "n/a", "na", "nan",
    or "undefined"). Also returns True for an actual None.
    For any other input, returns False. All exceptions are caught and
    result in False, ensuring the method does not raise during runtime.
    """
    try:
        if val is None:
            return True
        if not isinstance(val, str):
            return False
        s = val.strip().lower()
        null_values = {"none", "null", "nil", "n/a", "na", "nan", "undefined"}
        return s in null_values
    except Exception:
        return False

